<script lang="ts">
import { onMount } from 'svelte';
import type { ApexConfig, ApexDestination, ApexLocale } from '../../../core/src/apex/mod.ts';
import { whatsappUrl, formatUSD } from '../../../core/src/apex/mod.ts';
import Gallery from './Gallery.svelte';
let { config,destination,locale,reducedMotion=false }: {config:ApexConfig;destination:ApexDestination;locale:ApexLocale;reducedMotion?:boolean}=$props();
let selected=$state(0);
let paused=$state(false);
let gallery=$derived(destination.gallery.length?destination.gallery:[destination.image]);
let experiences=$derived(config.experiences.filter(x=>destination.experienceIds.includes(x.id)));
const ui=(es:string,en:string)=>locale==='es'?es:en;
onMount(()=>{const timer=setInterval(()=>{if(!paused&&!reducedMotion)selected=(selected+1)%gallery.length;},7000);return()=>clearInterval(timer);});
$effect(()=>{destination.id;selected=0;});
</script>
<section class="destination-page section svelte-16zl465">
 <div class="wrap"><a class="back-link" href="/#experiencias">← {ui('Todos los destinos','All destinations')}</a><div class="destination-heading svelte-16zl465"><div><p class="eyebrow">APEX / {ui('DESTINOS','DESTINATIONS')}</p><h1 class="svelte-16zl465">{destination.name}</h1><p class="muted">{destination.description[locale]}</p></div><section class="rotating-card svelte-18x4x6e" aria-label={destination.name}><div class="rotating-content svelte-18x4x6e"><div class="destination-card-photo svelte-16zl465"><img class="svelte-16zl465" src={gallery[selected]} alt={ui(`Vista conceptual de ${destination.name}`,`Conceptual view of ${destination.name}`)}/><span class="svelte-16zl465">{destination.name}</span></div></div><div class="rotation-controls svelte-18x4x6e"><button class="svelte-18x4x6e" aria-label={ui('Imagen anterior','Previous image')} onclick={()=>{selected=(selected-1+gallery.length)%gallery.length;paused=true;}}>←</button><span class="svelte-18x4x6e">{selected+1} / {gallery.length}</span><button class="svelte-18x4x6e" aria-label={ui('Imagen siguiente','Next image')} onclick={()=>{selected=(selected+1)%gallery.length;paused=true;}}>→</button><button class="svelte-10atlgt" aria-pressed={paused||reducedMotion} onclick={()=>paused=!paused}>{paused||reducedMotion?ui('▷ Reanudar','▷ Resume'):ui('Ⅱ Pausar','Ⅱ Pause')}</button></div></section></div><p class="apex-concept-note">{ui('Vistas conceptuales generadas con IA. No representan actividades incluidas.','AI-generated conceptual views. They do not represent included activities.')}</p></div>
 <div id="destination-details" class="wrap destination-details svelte-16grh86"><div class="detail-heading svelte-16grh86"><p class="eyebrow">{ui('EXPLORA','EXPLORE')} / {destination.name.toUpperCase()}</p><h2 class="svelte-16grh86">{destination.status==='available'?ui('Ciudad y aventura.','City and adventure.'):ui('La próxima historia está en camino.','The next story is on its way.')}</h2>{#if destination.id==='cdmx'}<p class="muted">{ui('CDMX y alrededores: La Marquesa está en el Estado de México y forma parte de esta colección regional.','CDMX and surroundings: La Marquesa is in the State of Mexico and forms part of this regional collection.')}</p>{/if}</div>
 {#if experiences.length}<div class="regional-grid svelte-16grh86">{#each experiences as experience}<article class="regional-card svelte-16grh86"><div class="regional-photo svelte-16grh86"><Gallery images={experience.gallery.length?experience.gallery:[experience.image]} title={experience.title[locale]} {locale} {reducedMotion} conceptual={experience.status==='coming-soon'}/></div><div class="regional-copy brand-panel svelte-16grh86"><span class="eyebrow">{experience.status==='available'?ui('CONFIRMADA · Experiencia Insignia','CONFIRMED · Signature Experience'):experience.status==='quote'?ui('EXPERIENCIA AÉREA','AERIAL EXPERIENCE'):ui('PRÓXIMAMENTE','COMING SOON')}</span><h3 class="svelte-16grh86">{experience.title[locale]}</h3><p class="svelte-16grh86">{#if experience.kind==='adventure'}{formatUSD(config.prices[2],locale)} {ui('para dos personas','for two people')} {/if}{experience.description[locale]}</p>{#if experience.status!=='coming-soon'}<a class="text-link" href={`/experiencias/${experience.id}/`}>{ui('Ver experiencia','View experience')} ↗</a>{#if experience.kind==='adventure'}<a class="text-link" href="/reservar/">{ui('Consultar disponibilidad','Check availability')} →</a>{/if}{:else}<a class="text-link" href={whatsappUrl(config,ui(`Hola APEX, me gustaría conocer las novedades de ${experience.title.es}.`,`Hi APEX, I would like to hear the latest about ${experience.title.en}.`))} target="_blank" rel="noopener noreferrer">{ui('Consultar novedades','Ask for updates')} ↗</a>{/if}</div></article>{/each}</div>
 {:else}<article class="apex-upcoming brand-panel"><span class="eyebrow">{ui('PRÓXIMAMENTE','COMING SOON')}{destination.id==='quintana-roo'?ui(' · EN DESARROLLO',' · IN DEVELOPMENT'):''}</span><h3>{destination.name}</h3><p>{ui('Estamos trabajando en nuevas experiencias para este destino. Compartiremos los detalles cuando estén confirmados; todavía no hay reservas abiertas.','We are working on new experiences for this destination. We will share the details when confirmed; reservations are not open yet.')}</p><a class="text-link" href={whatsappUrl(config,ui(`Hola APEX, me gustaría conocer las novedades de ${destination.name}.`,`Hi APEX, I would like to hear the latest about ${destination.name}.`))} target="_blank" rel="noopener noreferrer">{ui('Consultar novedades','Ask for updates')} ↗</a></article>{/if}
 <details class="destination-credits svelte-16grh86"><summary class="svelte-16grh86">{ui('Fotografías de los destinos','Destination photographs')}</summary><p>{ui('Las vistas de esta página son fotografías de referencia o imágenes conceptuales generadas con IA, según se indica. No garantizan actividades, rutas ni servicios incluidos.','This page uses reference photography or AI-generated conceptual imagery, as indicated. Images do not guarantee included activities, routes or services.')}</p><a href={config.brand.attributionsUrl ?? '#contacto'} target="_blank" rel="noopener noreferrer">{ui('Fuentes y licencias','Sources and licenses')} ↗</a></details>
 </div>
</section>
